CREATE TABLE public.telegram_links (user_id uuid PRIMARY KEY, grupo_id uuid NOT NULL REFERENCES public.grupos(id), telegram_user_id bigint UNIQUE, chat_id bigint UNIQUE, code_hash text UNIQUE, code_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.telegram_links TO authenticated;
GRANT ALL ON public.telegram_links TO service_role;
ALTER TABLE public.telegram_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_link ON public.telegram_links TO authenticated USING (user_id=auth.uid() AND public.e_membro(grupo_id) AND public.module_access('financas')) WITH CHECK (user_id=auth.uid() AND public.e_membro(grupo_id) AND public.module_access('financas') AND telegram_user_id IS NULL AND chat_id IS NULL);
CREATE TABLE public.telegram_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), update_id bigint NOT NULL UNIQUE, user_id uuid NOT NULL, grupo_id uuid NOT NULL REFERENCES public.grupos(id), chat_id bigint NOT NULL, file_id text, file_name text, mime_type text, file_path text, source_text text NOT NULL DEFAULT '', valor numeric(12,2), data date, emissao date, beneficiario text NOT NULL DEFAULT '', descricao text NOT NULL DEFAULT '', documento text NOT NULL DEFAULT 'outro', codigo text, categoria text NOT NULL DEFAULT 'Outros', conta text NOT NULL DEFAULT 'dinheiro', pago boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovado','descartado')), extraction_status text NOT NULL DEFAULT 'aguardando' CHECK(extraction_status IN ('aguardando','processando','concluido','erro')), error text, lancamento_id uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.telegram_reviews TO authenticated;
GRANT ALL ON public.telegram_reviews TO service_role;
ALTER TABLE public.telegram_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_reviews ON public.telegram_reviews FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.e_membro(grupo_id) AND public.module_access('financas'));
CREATE INDEX telegram_reviews_pending ON public.telegram_reviews(extraction_status,created_at) WHERE status='pendente';
CREATE TABLE public.telegram_ai_state (id boolean PRIMARY KEY DEFAULT true CHECK(id), paused boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.telegram_ai_state TO service_role;
ALTER TABLE public.telegram_ai_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY telegram_document_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='telegram-documents' AND EXISTS(SELECT 1 FROM public.telegram_reviews r WHERE r.file_path=name AND r.user_id=auth.uid() AND public.e_membro(r.grupo_id) AND public.module_access('financas')));
CREATE FUNCTION public.telegram_binding(_hash text,_telegram bigint,_chat bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.telegram_links; BEGIN SELECT * INTO l FROM public.telegram_links WHERE code_hash=_hash AND code_expires_at>now() FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.grupo_membros WHERE user_id=l.user_id AND grupo_id=l.grupo_id) THEN RETURN false; END IF; UPDATE public.telegram_links SET telegram_user_id=_telegram,chat_id=_chat,code_hash=NULL,code_expires_at=NULL WHERE user_id=l.user_id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.telegram_binding(text,bigint,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_binding(text,bigint,bigint) TO service_role;
CREATE FUNCTION public.telegram_claim(_id uuid) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ BEGIN UPDATE public.telegram_reviews SET extraction_status='processando' WHERE id=_id AND status='pendente' AND extraction_status='aguardando'; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.telegram_claim(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_claim(uuid) TO service_role;
CREATE FUNCTION public.telegram_review_action(_id uuid,_action text,_valor numeric DEFAULT NULL,_data date DEFAULT NULL,_descricao text DEFAULT '',_conta text DEFAULT 'dinheiro',_categoria text DEFAULT 'Outros',_pago boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r public.telegram_reviews; lid uuid; BEGIN
SELECT * INTO r FROM public.telegram_reviews WHERE id=_id FOR UPDATE;
IF NOT FOUND OR auth.uid() IS NULL OR r.user_id<>auth.uid() OR NOT public.e_membro(r.grupo_id) OR NOT public.module_access('financas') THEN RAISE EXCEPTION 'Sem acesso à conferência'; END IF;
IF r.status<>'pendente' THEN RETURN r.lancamento_id; END IF;
IF _action='descartar' THEN UPDATE public.telegram_reviews SET status='descartado',reviewed_at=now() WHERE id=_id; RETURN NULL; END IF;
IF _action NOT IN ('salvar','aprovar') OR _valor IS NULL OR _valor<=0 OR _valor>9999999999.99 OR _data IS NULL OR _data<DATE '2000-01-01' OR _data>DATE '2100-12-31' OR length(btrim(_descricao)) NOT BETWEEN 1 AND 200 OR _conta NOT IN ('dinheiro','alimentacao','refeicao') OR length(_categoria)>100 THEN RAISE EXCEPTION 'Revise valor, data, descrição e carteira'; END IF;
IF _action='aprovar' THEN INSERT INTO public.lancamentos(grupo_id,tipo,descricao,valor,data,pago,conta,destino,origem_modulo,criado_por) VALUES(r.grupo_id,'debito',btrim(_descricao),_valor,_data,_pago,_conta,'geral','financas',auth.uid()) RETURNING id INTO lid; END IF;
UPDATE public.telegram_reviews SET valor=_valor,data=_data,descricao=btrim(_descricao),conta=_conta,categoria=_categoria,pago=_pago,status=CASE WHEN _action='aprovar' THEN 'aprovado' ELSE 'pendente' END,lancamento_id=lid,reviewed_at=CASE WHEN _action='aprovar' THEN now() ELSE NULL END WHERE id=_id;
RETURN lid; END $$;
GRANT UPDATE ON public.telegram_reviews TO authenticated;
CREATE POLICY review_rpc_update ON public.telegram_reviews FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.e_membro(grupo_id) AND public.module_access('financas')) WITH CHECK(user_id=auth.uid() AND public.e_membro(grupo_id) AND public.module_access('financas'));
REVOKE ALL ON FUNCTION public.telegram_review_action(uuid,text,numeric,date,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.telegram_review_action(uuid,text,numeric,date,text,text,text,boolean) TO authenticated;